<template>
  <main class="space-y-5 pb-10" dir="rtl">
    <div class="flex flex-wrap justify-between gap-3"><div><h2 class="text-2xl font-bold">اموال خسارتی و تعمیرات</h2><p class="text-sm text-slate-500">پیگیری هر شماره اموال و بدهی تعمیرکننده‌ها</p></div><div class="flex gap-2"><button class="primary" @click="createOpen = !createOpen">ثبت پرونده</button><button class="secondary" @click="repairersOpen = !repairersOpen">تعمیرکننده‌ها و پرداخت‌ها</button></div></div>
    <p v-if="error" class="rounded bg-red-50 p-3 text-red-700">{{ error }}</p><p v-if="notice" class="rounded bg-emerald-50 p-3 text-emerald-700">{{ notice }}</p>
    <section v-if="createOpen" class="panel"><h3 class="mb-3 font-bold">پرونده جدید برای یک واحد کالا</h3><form class="grid gap-3 md:grid-cols-2" @submit.prevent="createAsset">
      <label>منبع پرونده<select v-model="form.return_event_item_id" class="field" @change="selectCandidate"><option value="">مستقل / سرویس دوره‌ای</option><option v-for="candidate in candidates" :key="candidate.return_event_item_id" :value="candidate.return_event_item_id">لیست {{ candidate.list_number }} · {{ candidate.product_name_snapshot }} · {{ candidate.unregistered_quantity }} واحد</option></select></label>
      <label>محصول<select v-model="form.product_id" class="field" :disabled="!!form.return_event_item_id" required><option value="">انتخاب محصول</option><option v-for="product in products" :key="product.id" :value="product.id">{{ product.name }}</option></select></label>
      <label>شماره اموال<input v-model.trim="form.asset_number" class="field" required /></label><label v-if="!form.return_event_item_id">مشتری (اختیاری)<select v-model="form.customer_id" class="field" @change="loadCustomerInvoices"><option value="">بدون مشتری</option><option v-for="customer in customers" :key="customer.id" :value="customer.id">{{ customer.name }}</option></select></label>
      <label v-if="!form.return_event_item_id && form.customer_id">فاکتور مرتبط<select v-model="form.related_invoice_id" class="field" required><option value="">انتخاب فاکتور</option><option v-for="invoice in customerInvoices" :key="invoice.id" :value="invoice.id">{{ invoice.invoice_number || `شماره ${invoice.id}` }} · {{ faDate(invoice.issued_at || invoice.date) }}</option></select></label>
      <label class="md:col-span-2">شرح ایراد یا خسارت<textarea v-model.trim="form.issue_description" class="field" required /></label><button class="primary w-fit" :disabled="busy">ثبت پرونده</button>
    </form></section>
    <section v-if="repairersOpen" class="panel space-y-4"><h3 class="font-bold">تعمیرکننده‌ها و مراکز تعمیر</h3><form class="flex flex-wrap items-end gap-2" @submit.prevent="saveRepairer"><label>نام<input v-model.trim="repairerForm.name" class="field" required /></label><label>تلفن<input v-model.trim="repairerForm.phone" class="field" /></label><label>توضیحات<input v-model.trim="repairerForm.notes" class="field" /></label><button class="primary" :disabled="busy">{{ repairerForm.id ? 'ذخیره تغییرات' : 'افزودن' }}</button><button v-if="repairerForm.id" type="button" class="secondary" @click="resetRepairer">انصراف</button></form>
      <div v-for="repairer in repairers" :key="repairer.id" class="rounded-lg border p-3"><div class="flex flex-wrap justify-between gap-2"><div><strong>{{ repairer.name }}</strong><span class="mr-3 text-slate-500">{{ repairer.phone }}</span><p>بدهی: {{ fmt(repairer.due) }} تومان · پرداخت: {{ fmt(repairer.paid) }} تومان</p></div><div class="flex gap-2"><button class="link" @click="editRepairer(repairer)">ویرایش</button><button class="link" @click="openPayments(repairer)">پرداخت‌ها</button><button class="text-red-700" @click="deleteRepairer(repairer)">حذف</button></div></div>
        <div v-if="paymentRepairer?.id === repairer.id" class="mt-3 border-t pt-3"><form class="flex flex-wrap items-end gap-2" @submit.prevent="recordPayment"><label>مبلغ (تومان)<input v-model.number="paymentForm.amount_toman" type="number" min="1" :max="repairer.due" class="field" required /></label><label>تاریخ پرداخت<JalaliDatePicker v-model="paymentForm.paid_at" /></label><label>توضیح<input v-model.trim="paymentForm.notes" class="field" /></label><button class="primary" :disabled="busy || !repairer.due">ثبت پرداخت</button></form><p class="mt-2 text-xs text-slate-500">پرداخت به ترتیب قدیمی‌ترین بدهی‌ها به اقلام اختصاص می‌یابد.</p><ul class="mt-2"><li v-for="payment in payments" :key="payment.id">{{ faDate(payment.paid_at) }} · {{ fmt(payment.amount_toman) }} تومان · {{ payment.notes }}</li></ul></div>
      </div></section>
    <section class="panel"><div class="mb-3 flex flex-wrap justify-between gap-2"><h3 class="font-bold">پرونده‌ها ({{ filteredAssets.length }})</h3><div class="flex gap-2"><input v-model.trim="search" class="field" placeholder="جست‌وجوی محصول، اموال، تعمیرکننده" /><select v-model="statusFilter" class="field"><option value="">همه وضعیت‌ها</option><option v-for="(label, key) in statuses" :key="key" :value="key">{{ label }}</option></select></div></div><p v-if="loading">در حال بارگذاری...</p><p v-else-if="!filteredAssets.length">پرونده‌ای پیدا نشد.</p>
      <article v-for="asset in filteredAssets" :key="asset.id" class="mb-3 rounded-lg border p-4"><div class="flex flex-wrap justify-between gap-2"><div><strong>{{ asset.product_name_snapshot }}</strong><span class="mr-3">شماره اموال: {{ asset.asset_number }}</span><p class="text-slate-600">{{ asset.issue_description }}</p><p class="text-xs text-slate-500">{{ asset.list_number ? `لیست ${asset.list_number}` : 'ثبت مستقل' }} · {{ asset.customer_name }}</p></div><span class="h-fit rounded-full bg-slate-100 px-3 py-1">{{ statuses[asset.status] }}</span></div>
        <div v-if="asset.repairer_id" class="mt-3 grid gap-1 md:grid-cols-3"><span>تعمیرکننده: {{ asset.repairer_name }}</span><span>ارسال: {{ faDate(asset.sent_at) }}</span><span>برگشت: {{ faDate(asset.returned_at) || 'ثبت نشده' }}</span><span>هزینه تعمیر: {{ fmt(asset.repair_cost_toman) }} تومان</span><span>پرداخت: {{ fmt(asset.repair_paid_toman) }} تومان</span><span>مانده: {{ fmt(asset.repair_due_toman) }} تومان <b v-if="asset.repair_cost_toman">({{ asset.repair_due_toman === 0 ? 'تسویه کامل' : asset.repair_paid_toman ? 'تسویه جزئی' : 'پرداخت‌نشده' }})</b></span></div><p v-if="asset.damage_amount_toman" class="mt-2">خسارت مشتری: {{ fmt(asset.damage_amount_toman) }} تومان <span v-if="asset.invoice_number">· فاکتور {{ asset.invoice_number }}</span></p>
        <div class="mt-3 flex flex-wrap gap-2"><button v-if="asset.status === 'NEEDS_FOLLOW_UP'" class="secondary" @click="openAction(asset, 'send')">ارسال به تعمیر</button><button v-if="asset.status === 'REPAIR'" class="secondary" @click="openAction(asset, 'return')">برگشت از تعمیر</button><button v-if="canDecide(asset)" class="secondary" @click="openAction(asset, 'resolve')">مشکل برطرف شد</button><button v-if="asset.customer_id && canDecide(asset)" class="secondary" @click="openAction(asset, 'assess')">تعیین خسارت</button><button v-if="asset.status === 'DAMAGE_ASSESSED'" class="secondary" @click="invoiceAsset(asset)">ثبت در فاکتور</button><button v-if="asset.invoice_id" class="secondary" @click="downloadInvoice(asset)">دانلود فاکتور</button><button v-if="asset.status === 'INVOICED'" class="secondary" @click="sendInvoice(asset)">ثبت ارسال فاکتور</button><button v-if="asset.status === 'INVOICED' && asset.delivery_list_id" class="secondary" @click="$router.push(`/lists/${asset.delivery_list_id}`)">مشاهده فاکتور</button><button v-if="!asset.invoice_id" class="secondary" @click="openAction(asset, 'details')">ویرایش</button></div>
      </article></section>
    <div v-if="actionAsset" class="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4" @click.self="actionAsset = null"><form class="w-full max-w-lg space-y-3 rounded-xl bg-white p-5" @submit.prevent="saveAction"><h3 class="font-bold">{{ actionTitles[actionKind] }} · {{ actionAsset.product_name_snapshot }}</h3><template v-if="actionKind === 'send'"><label>تعمیرکننده<select v-model="actionForm.repairer_id" class="field" required><option value="">انتخاب کنید</option><option v-for="repairer in repairers" :key="repairer.id" :value="repairer.id">{{ repairer.name }}</option></select></label><label>تاریخ ارسال<JalaliDatePicker v-model="actionForm.sent_at" /></label></template><template v-if="actionKind === 'return'"><label>تاریخ برگشت<JalaliDatePicker v-model="actionForm.returned_at" /></label><label>هزینه تعمیر (تومان)<input v-model.number="actionForm.repair_cost_toman" type="number" min="0" class="field" required /></label></template><template v-if="actionKind === 'assess'"><label>مبلغ خسارت (تومان)<input v-model.number="actionForm.damage_amount_toman" type="number" min="1" class="field" required /></label></template><template v-if="actionKind === 'details'"><label>شماره اموال<input v-model.trim="actionForm.asset_number" class="field" required /></label><label>شرح ایراد<textarea v-model.trim="actionForm.issue_description" class="field" required /></label></template><div class="flex gap-2"><button class="primary" :disabled="busy">ثبت</button><button type="button" class="secondary" @click="actionAsset = null">انصراف</button></div></form></div>
  </main>
</template>
<script setup>
import { computed, onMounted, reactive, ref } from 'vue';
import JalaliDatePicker from '../JalaliDatePicker.vue';
import { toGregorianDate, toPersianDate } from '../../utils/dateConverter';
import { getApiErrorMessage } from '../../utils/apiError';
import { damagedAssetService as service } from '../../modules/damaged-assets/api/damagedAsset.service';
import { productService } from '../../modules/products/api/product.service';
import { invoiceService } from '../../modules/invoices/api/invoice.service';
const statuses = { NEEDS_FOLLOW_UP: 'نیاز به پیگیری', REPAIR: 'در تعمیر', RETURNED: 'برگشته از تعمیر', DAMAGE_ASSESSED: 'در انتظار ثبت فاکتور خسارت', INVOICED: 'تعیین خسارت (فاکتور صادر شد)', COMPLETED: 'تکمیل' };
const actionTitles = { send: 'ارسال به تعمیر', return: 'برگشت از تعمیر', resolve: 'رفع مشکل و تکمیل', assess: 'ثبت مبلغ خسارت', details: 'ویرایش پرونده' };
const assets = ref([]), candidates = ref([]), repairers = ref([]), products = ref([]), customers = ref([]), customerInvoices = ref([]), payments = ref([]);
const loading = ref(false), busy = ref(false), error = ref(''), notice = ref(''), createOpen = ref(false), repairersOpen = ref(false);
const search = ref(''), statusFilter = ref(''), actionAsset = ref(null), actionKind = ref(''), paymentRepairer = ref(null);
const actionForm = reactive({}), form = reactive({ return_event_item_id: '', product_id: '', customer_id: '', related_invoice_id: '', asset_number: '', issue_description: '' });
const repairerForm = reactive({ id: null, name: '', phone: '', notes: '' }), paymentForm = reactive({ amount_toman: '', paid_at: '', notes: '' });
const fmt = (v) => Number(v || 0).toLocaleString('fa-IR');
const faDate = (v) => v ? toPersianDate(String(v).slice(0, 10)) : '';
const isoDate = (v) => `${toGregorianDate(v)}T12:00:00+03:30`;
const canDecide = (asset) => ['NEEDS_FOLLOW_UP', 'RETURNED'].includes(asset.status);
const filteredAssets = computed(() => assets.value.filter((a) => (!statusFilter.value || a.status === statusFilter.value) && (!search.value || [a.product_name_snapshot, a.asset_number, a.repairer_name, a.customer_name].some((v) => String(v || '').toLowerCase().includes(search.value.toLowerCase())))));
async function refresh() { loading.value = true; try { const [a, c, r] = await Promise.all([service.getAssets(), service.getCandidates(), service.getRepairers()]); assets.value = a.data.assets; candidates.value = c.data.candidates; repairers.value = r.data.repairers; } catch (e) { error.value = getApiErrorMessage(e); } finally { loading.value = false; } }
async function perform(task, message) { busy.value = true; error.value = ''; notice.value = ''; try { await task(); notice.value = message; await refresh(); return true; } catch (e) { error.value = getApiErrorMessage(e); return false; } finally { busy.value = false; } }
function selectCandidate() { const c = candidates.value.find((v) => v.return_event_item_id === Number(form.return_event_item_id)); form.product_id = c?.product_id || ''; form.customer_id = c?.customer_id || ''; form.issue_description = c?.damage_notes || ''; }
async function loadCustomerInvoices() { form.related_invoice_id = ''; customerInvoices.value = []; if (!form.customer_id) return; try { customerInvoices.value = (await invoiceService.getCustomerInvoices(form.customer_id)).data.invoices.filter((invoice) => invoice.status === 'ISSUED' || !invoice.status); } catch (e) { error.value = getApiErrorMessage(e); } }
async function createAsset() { const payload = { ...form, product_id: Number(form.product_id), return_event_item_id: form.return_event_item_id || null, customer_id: form.customer_id || null, related_invoice_id: form.related_invoice_id || null }; if (await perform(() => service.createAsset(payload), 'پرونده ثبت شد')) { Object.assign(form, { return_event_item_id: '', product_id: '', customer_id: '', related_invoice_id: '', asset_number: '', issue_description: '' }); createOpen.value = false; } }
function resetRepairer() { Object.assign(repairerForm, { id: null, name: '', phone: '', notes: '' }); }
function editRepairer(r) { Object.assign(repairerForm, { id: r.id, name: r.name, phone: r.phone || '', notes: r.notes || '' }); }
async function saveRepairer() { const p = { name: repairerForm.name, phone: repairerForm.phone, notes: repairerForm.notes }; if (await perform(() => repairerForm.id ? service.updateRepairer(repairerForm.id, p) : service.createRepairer(p), 'تعمیرکننده ذخیره شد')) resetRepairer(); }
async function deleteRepairer(r) { if (window.confirm(`تعمیرکننده «${r.name}» حذف شود؟`)) await perform(() => service.deleteRepairer(r.id), 'تعمیرکننده حذف شد'); }
async function openPayments(r) { paymentRepairer.value = r; try { payments.value = (await service.getPayments(r.id)).data.payments; } catch (e) { error.value = getApiErrorMessage(e); } }
async function recordPayment() { if (!paymentForm.paid_at) { error.value = 'تاریخ پرداخت را انتخاب کنید'; return; } const id = paymentRepairer.value.id; if (await perform(() => service.recordPayment(id, { ...paymentForm, paid_at: isoDate(paymentForm.paid_at) }), 'پرداخت ثبت شد')) { Object.assign(paymentForm, { amount_toman: '', paid_at: '', notes: '' }); await openPayments(repairers.value.find((r) => r.id === id)); } }
function openAction(a, kind) { actionAsset.value = a; actionKind.value = kind; Object.keys(actionForm).forEach((key) => delete actionForm[key]); Object.assign(actionForm, { asset_number: a.asset_number, issue_description: a.issue_description, repair_cost_toman: 0 }); }
async function saveAction() { if (['send', 'return'].includes(actionKind.value) && !actionForm[actionKind.value === 'send' ? 'sent_at' : 'returned_at']) { error.value = 'تاریخ را انتخاب کنید'; return; } const p = { ...actionForm, operation: actionKind.value }; if (p.sent_at) p.sent_at = isoDate(p.sent_at); if (p.returned_at) p.returned_at = isoDate(p.returned_at); if (await perform(() => service.updateAsset(actionAsset.value.id, p), 'وضعیت پرونده ثبت شد')) actionAsset.value = null; }
async function invoiceAsset(a) { if (window.confirm(`مبلغ ${fmt(a.damage_amount_toman)} تومان خسارت در فاکتور ثبت شود؟`)) await perform(() => service.issueInvoice(a.id), 'هزینه خسارت در فاکتور ثبت شد'); }
async function sendInvoice(a) { if (window.confirm(`ارسال فاکتور ${a.invoice_number || ''} به مشتری ثبت شود؟`)) await perform(() => service.sendInvoice(a.id, { channel: 'MANUAL' }), 'ارسال فاکتور ثبت شد و پرونده تکمیل شد'); }
async function downloadInvoice(a) { error.value = ''; try { const payload = (await service.downloadInvoice(a.id)).data; const binary = atob(payload.data_base64); const bytes = Uint8Array.from(binary, (char) => char.charCodeAt(0)); const url = URL.createObjectURL(new Blob([bytes], { type: 'application/pdf' })); const link = document.createElement('a'); link.href = url; link.download = payload.filename; link.click(); window.setTimeout(() => URL.revokeObjectURL(url), 1000); } catch (e) { error.value = getApiErrorMessage(e); } }
onMounted(async () => { await refresh(); const [p, c] = await Promise.allSettled([productService.getCatalog(), invoiceService.getCustomers()]); if (p.status === 'fulfilled') products.value = p.value.data.products || []; if (c.status === 'fulfilled') customers.value = c.value.data || []; });
</script>
<style scoped>
.panel { background: white; border: 1px solid #e2e8f0; border-radius: .75rem; padding: 1.25rem; }
.field { display: block; width: 100%; min-width: 10rem; margin-top: .3rem; border: 1px solid #cbd5e1; border-radius: .5rem; padding: .5rem .7rem; background: white; }
.primary { background: #047857; color: white; border-radius: .5rem; padding: .5rem 1rem; }
.secondary { border: 1px solid #94a3b8; border-radius: .5rem; padding: .5rem 1rem; }
.link { color: #0369a1; }
</style>
